const schema = [{"@context":"https://schema.org","@type":"Service","name":"Interpretation &amp; visualisation","serviceType":"Research service","provider":{"@type":"Organization","name":"Pubrica","url":"https://pubrica.com/"},"url":"https://pubrica.com/services/data-analytics-machine-learning/interpretation-reporting-and-visualisation/","description":"Statistical output turned into interpretation a reader can follow, reports built to CONSORT, PRISMA, STROBE and TRIPOD.","areaServed":"Worldwide","audience":{"@type":"Audience","audienceType":"Researchers, PhD scholars, research institutions, medical writers and life-science teams"}},{"@context":"https://schema.org","@type":"FAQPage","mainEntity":[{"@type":"Question","name":"Who uses this service?","acceptedAnswer":{"@type":"Answer","text":"Researchers preparing manuscripts, clinicians and sponsors compiling regulatory submissions, institutions and students presenting theses, and organisations that need decisions taken from analysis.\n\nThe common situation is an analysis that is finished and a write-up that has not started, or has started and is not carrying the result."}},{"@type":"Question","name":"What kinds of report do you produce?","acceptedAnswer":{"@type":"Answer","text":"Journal-ready manuscripts, clinical study reports, white papers, regulatory documents, business reports and academic submissions, each to the guideline and format that applies.\n\nWhere a study has a reporting guideline, it is named on the order and the checklist is completed and delivered with the report."}},{"@type":"Question","name":"Do you follow international reporting guidelines?","acceptedAnswer":{"@type":"Answer","text":"Yes — CONSORT for trials, PRISMA for reviews, STROBE for observational studies, TRIPOD for prediction models, plus ICH, GCP and journal-specific requirements.\n\nA declared guideline is a checkable claim, and it is checked. Finding six unreported items before submission is routine; finding them in review is not."}},{"@type":"Question","name":"What kinds of figure do you produce?","acceptedAnswer":{"@type":"Answer","text":"For clinical and epidemiological work: CONSORT flow diagrams, Kaplan–Meier curves, forest plots, heatmaps, scatter and regression plots, and properly formatted data tables.\n\nThe figure type follows the shape of the result. A survival difference shown as a bar chart of means has discarded the timing, which was the finding."}},{"@type":"Question","name":"How do you make sure the interpretation is right?","acceptedAnswer":{"@type":"Answer","text":"It is drafted against the statistical output rather than a summary of it, and checked by a second reader who did not write it — against the output and against the checklist.\n\nThe most common correction is a statement pitched more strongly than the interval supports. It is easy to make, hard to see in your own writing, and expensive when a reviewer finds it."}},{"@type":"Question","name":"Can you re-run the analysis if something looks wrong?","acceptedAnswer":{"@type":"Answer","text":"Not inside this service. If the interpretation stage turns up something that looks like an analysis problem, we raise it rather than quietly correct it.\n\nRe-analysis is biostatistics and is quoted separately, deliberately — the person interpreting a result should not also be the person who produced it."}}]},{"@context":"https://schema.org","@type":"BreadcrumbList","itemListElement":[{"@type":"ListItem","position":1,"name":"Home","item":"https://pubrica.com/"},{"@type":"ListItem","position":2,"name":"Data analytics","item":"https://pubrica.com/services/data-analytics-machine-learning/"},{"@type":"ListItem","position":3,"name":"Data analytics","item":"https://pubrica.com/services/data-analytics-machine-learning/interpretation-reporting-and-visualisation/"}]}];

